/// <reference lib="webworker" />
/**
 * Database Worker: loads the Rust runtime (forge-wasm) and serves the page's requests.
 *
 * Must be a *dedicated* Worker: the OPFS storage needs `FileSystemSyncAccessHandle`,
 * which a SharedWorker does not have (verified; see ADR 0002), and only one Worker
 * may own the database at a time (the page arranges that with a Web Lock).
 *
 * Build the wasm first: `just wasm-bundle` (writes ../pkg).
 */

// @ts-ignore -- generated by `just wasm-bundle`; absent until then
import init, { start, request, exportDatabase, importDatabase } from '../pkg/forge_wasm.js'
import type { ExportInfo, WorkerReply, WorkerRequest } from './protocol'

let loaded: Promise<unknown> | undefined

async function handle(msg: WorkerRequest): Promise<unknown> {
  loaded ??= init()
  await loaded

  switch (msg.op) {
    case 'start':
      return JSON.parse(await start())
    case 'request': {
      const res = await request(msg.method, msg.path, JSON.stringify(msg.headers), msg.body)
      return { status: res.status, headers: res.headers, body: res.body }
    }
    case 'export':
      return exportDatabase() as ExportInfo
    case 'import':
      return JSON.parse(importDatabase(msg.bytes))
  }
}

self.onmessage = async (event: MessageEvent<WorkerRequest>) => {
  const msg = event.data
  let reply: WorkerReply
  try {
    reply = { id: msg.id, ok: true, result: await handle(msg) }
  } catch (e) {
    reply = { id: msg.id, ok: false, error: e instanceof Error ? e.message : String(e) }
  }
  // Transfer binary results instead of copying them.
  // A response carries its payload in `body`, an export in `bytes`.
  const result = reply.ok ? reply.result : undefined
  const parts = result && typeof result === 'object' ? (result as { body?: unknown; bytes?: unknown }) : {}
  const transfer: Transferable[] = [parts.body, parts.bytes]
    .filter((part): part is Uint8Array => part instanceof Uint8Array)
    .map((part) => part.buffer as ArrayBuffer)
  ;(self as unknown as Worker).postMessage(reply, transfer)
}
